extern "C" unsigned int strlen(const char *);

class string_buf {
public:
    unsigned long long *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
};

class stringx {
    char *chars;
    string_buf *my_buf;

public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    void append(const char *, int = -1);
    void append(const stringx &);
    void make_room(int);

    friend stringx operator+(const char *, const stringx &);
    friend stringx operator+(const stringx &, const char *);
};

inline stringx operator+(const char *lhs, const stringx &rhs)
{
    stringx foo;
    int len = strlen(lhs);
    foo.make_room(len + rhs.my_buf->char_length);
    foo.append(lhs, len);
    foo.append(rhs);
    return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
    stringx foo;
    int len = strlen(rhs);
    foo.make_room(len + lhs.my_buf->char_length);
    foo.append(lhs);
    foo.append(rhs, len);
    return foo;
}

class entity_id {
    void *value;
public:
    stringx get_val() const;
};

class entity {
public:
    bool is_a_beam() const
    {
        char *table = *(char **)this;
        short adjustment = *(short *)(table + 0x2d0);
        bool (*method)(const void *) =
            *(bool (**)(const void *))(table + 0x2d4);
        return method((const char *)this + adjustment);
    }

    entity_id get_id() const
    {
        return *(const entity_id *)((const char *)this + 0x80);
    }
};

class script_object {
    char padding[4];
    stringx name;
public:
    const stringx &get_name() const { return name; }
};

class vm_executable {
    char padding[12];
    stringx fullname;
public:
    const stringx &get_fullname() const { return fullname; }
};

class vm_thread {
    script_object *instance;
    vm_executable *executable;
public:
    script_object *get_instance() const { return instance; }
    vm_executable *get_executable() const { return executable; }
    void slf_error(const stringx &);
};

class vm_stack {
    int salloc;
    char *buffer;
    char *SP;
    vm_thread *my_thread;
public:
    void pop(int size) { SP -= size; }
    char *get_SP() const { return SP; }
    vm_thread *get_thread() const { return my_thread; }
    bool push(const char *, int);
};

class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    };
};

typedef entity *vm_entity_t;
typedef entity *vm_beam_t;

void error(const stringx &);

#define SLF_PARMS \
    stack.pop(sizeof(parms_t)); \
    parms_t *parms = (parms_t *)stack.get_SP()
#define SLF_RETURN \
    if (!stack.push((char *)&result, sizeof(result))) \
        error(stack.get_thread()->get_instance()->get_name() + \
              ": stack overflow in " + \
              stack.get_thread()->get_executable()->get_fullname())
#define SLF_DONE return true

class slf_to_beam_t : public script_library_class::function {
public:
    struct parms_t {
        vm_entity_t e;
    };

    bool operator()(vm_stack &stack, entry_t entry);
};

bool slf_to_beam_t::operator()(vm_stack &stack, entry_t entry)
{
    SLF_PARMS;
    vm_beam_t result = 0;
    if (parms->e->is_a_beam())
        result = static_cast<vm_beam_t>(parms->e);
    else
    {
        stack.get_thread()->slf_error(
            "to_beam(): " + parms->e->get_id().get_val() + " is not a beam");
    }
    SLF_RETURN;
    SLF_DONE;
}
